contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function test(
        uint64 _number,
        uint64 _timestamp,
        uint256 _basefee,
        bytes32 _hash,
        uint64 _sequenceNumber,
        bytes32 _batcherHash,
        uint256 _l1FeeOverhead,
        uint256 _l1FeeScalar
    ) public {
        require(msg.sender != 0xDeaDDEaDDeAdDeAdDEAdDEaddeAddEAdDEAd0001);
        bool ok; c.setL1BlockValues(_number, _timestamp, _basefee, _hash, _sequenceNumber, _batcherHash, _l1FeeOverhead, _l1FeeScalar); bool __rev0 = __ESBMC_reverted(); if (__rev0) { ok = false; } else { ok = true; }
        assert(!ok);
    }

    receive() external payable {}
    fallback() external payable {}
}

